69:     public static Result parse(String body, boolean truncated, Collection<String> requestedIds) {
70:         if (truncated) {
71:             return new Result(Collections.<String, String>emptyMap(), FAILURE_TRUNCATED);
72:         }
73: 
74:         if (body == null || body.trim().isEmpty()) {
75:             return new Result(Collections.<String, String>emptyMap(), FAILURE_EMPTY);
76:         }
77: 
78:         JSONArray items;
79: 
80:         try {
81:             JSONObject root = new JSONObject(body);
82:             // Chat Completions wraps the model's JSON in message.content. The old parser
83:             // treated every real API response as missing items; fixtures only supplied content.
84:             if (root.has("choices")) {
85:                 JSONObject choice = root.getJSONArray("choices").getJSONObject(0);
86:                 if ("length".equals(choice.optString("finish_reason"))) {
87:                     return new Result(Collections.<String, String>emptyMap(), FAILURE_TRUNCATED);
88:                 }
89:                 if (!"stop".equals(choice.optString("finish_reason"))) {
90:                     return new Result(Collections.<String, String>emptyMap(), FAILURE_MALFORMED);
91:                 }
92:                 Object content = choice.getJSONObject("message").opt("content");
93:                 if (!(content instanceof String)) {
94:                     return new Result(Collections.<String, String>emptyMap(), FAILURE_EMPTY);
95:                 }
96:                 root = new JSONObject((String) content);
97:             }
98:             items = root.optJSONArray("items");
99:         } catch (JSONException e) {
100:             return new Result(Collections.<String, String>emptyMap(), FAILURE_MALFORMED);
101:         }
102: 
103:         if (items == null) {
104:             return new Result(Collections.<String, String>emptyMap(), FAILURE_NO_ITEMS);
105:         }
106: 
107:         Set<String> requested = requestedIds == null ? Collections.<String>emptySet() : new HashSet<>(requestedIds);
108:         Map<String, Integer> occurrences = new HashMap<>();
109:         Map<String, String> candidates = new LinkedHashMap<>();
110: 
111:         for (int i = 0; i < items.length(); i++) {
112:             JSONObject item = items.optJSONObject(i);
113: 
114:             if (item == null) {
115:                 continue;
116:             }
117: 
118:             String id = item.optString("id", null);
119: 
120:             if (id == null || !requested.contains(id)) {
121:                 continue; // unknown id: dropped, never guessed onto another entry
122:             }
123: 
124:             occurrences.put(id, occurrences.containsKey(id) ? occurrences.get(id) + 1 : 1);
125: 
126:             Object raw = item.opt("translation");
127: 
128:             if (!(raw instanceof String)) {
129:                 continue;
130:             }
131: 
132:             String translation = (String) raw;
133: 
134:             if (translation.trim().isEmpty() || translation.codePointCount(0, translation.length()) > MAX_TRANSLATION_CODE_POINTS) {
135:                 continue;
136:             }
137: 
138:             candidates.put(id, translation);
139:         }
140: 
141:         Map<String, String> translations = new LinkedHashMap<>();
142: 
143:         for (Map.Entry<String, String> entry : candidates.entrySet()) {
144:             // A duplicated id is void: the service broke the id protocol for that entry.
145:             if (occurrences.get(entry.getKey()) == 1) {
146:                 translations.put(entry.getKey(), entry.getValue());
147:             }
148:         }
149: 
150:         return new Result(translations, !requested.isEmpty() && translations.isEmpty()
151:                 ? FAILURE_NO_TRANSLATIONS : null);
152:     }

55:     public void bind(List<MediaSubtitle> subtitles, List<SubtitleFormatCandidate> candidates) {
56:         clear();
57:         mGeneration++;
58: 
59:         if (subtitles == null || candidates == null) {
60:             return;
61:         }
62: 
63:         Map<String, List<MediaSubtitle>> byUrl = new HashMap<>();
64: 
65:         for (MediaSubtitle subtitle : subtitles) {
66:             if (subtitle == null || subtitle.getBaseUrl() == null) {
67:                 continue;
68:             }
69: 
70:             List<MediaSubtitle> bucket = byUrl.get(subtitle.getBaseUrl());
71: 
72:             if (bucket == null) {
73:                 bucket = new ArrayList<>();
74:                 byUrl.put(subtitle.getBaseUrl(), bucket);
75:             }
76: 
77:             boolean duplicate = false;
78:             for (MediaSubtitle existing : bucket) {
79:                 if (sameSource(existing, subtitle)) {
80:                     duplicate = true;
81:                     break;
82:                 }
83:             }
84:             if (!duplicate) {
85:                 bucket.add(subtitle);
86:             }
87:         }
88: 
89:         for (SubtitleFormatCandidate candidate : candidates) {
90:             if (candidate == null || candidate.getFormat() == null) {
91:                 continue;
92:             }
93: 
94:             List<MediaSubtitle> matches = candidate.getBaseUrl() != null ? byUrl.get(candidate.getBaseUrl()) : null;
95: 
96:             if (matches == null || matches.size() != 1) {
97:                 // 0 matches: the source list and the manifest disagree.
98:                 // 2+ matches: the URL cannot identify one source. Never pick the first candidate.
99:                 mUnresolvedByFormat.put(candidate.getFormat(), matches != null && matches.size() > 1);
100:                 mRejectedCount++;
101:                 continue;
102:             }
103: 
104:             mSourceByFormat.put(candidate.getFormat(), SelectedSubtitleSource.from(matches.get(0), candidate.getBaseUrl(), mGeneration));
105:             mBoundCount++;
106:         }
107:     }
156:     private static boolean sameSource(MediaSubtitle a, MediaSubtitle b) {
157:         return equal(a.getVssId(), b.getVssId()) && equal(a.getLanguageCode(), b.getLanguageCode())
158:                 && equal(a.getType(), b.getType()) && equal(a.getMimeType(), b.getMimeType())
159:                 && equal(a.getCodecs(), b.getCodecs()) && a.isTranslatable() == b.isTranslatable();
160:     }
